        "settings_changelog_v7_item_3": "Fahrzeug-Avatar optimiert: Bilder werden asynchron und speicherschonend skaliert geladen",
        "settings_changelog_v7_item_4": "Walkthrough-Overlay überarbeitet: präzisere Spotlight-Darstellung und zuverlässigere Touch-Blockierung",
        "settings_changelog_v7_title": "Version 1.2.4",
        "settings_changelog_v8_item_1": "Neue Sprachen: Spanisch, Italienisch und Portugiesisch verfügbar",
        "settings_changelog_v8_item_4": "Fahrzeug-Navigation stabilisiert und Dialoge auf Geräten mit Display-Ausschnitt verbessert",
