        "settings_changelog_v8_title": "Version 1.2.5",
        "settings_changelog_v9_item_1": "Stabilized fullscreen landscape view: no more freeze when rotating in gear and exhaust calculators",
        "settings_changelog_v9_item_2": "Optimized fullscreen dialogs: one-time window setup instead of reconfiguring on every redraw",
