        "settings_data_processing_title": "Data processing",
        "settings_detail_changelog_intro": "What's new in version 1.2.7 and overview of older versions.",
        "settings_detail_contact_form_title": "Contact form",
        "settings_detail_contact_intro": "Write to us directly from the app – questions, feedback, suggestions or bug reports with automatically attached device information.",
        "settings_detail_help_faq_answer_1": "The app offers various calculators for common 2-stroke engine calculations. You can find all available modules in the calculator overview.",
        "settings_detail_help_faq_answer_2": "Calculator inputs are processed locally and not stored permanently. With an account, vehicle data (master data, maintenance, fuel log) is synced to the cloud.",
        "settings_detail_help_faq_answer_3": "Each calculator uses fixed units suited to the calculation – mostly metric (mm, cc, °, km/h, etc.). There is no option to switch between metric and imperial units.",
        "settings_detail_help_faq_answer_4": "Go to Settings → Appearance → Menu type to switch between bottom menu and side panel.",
        "settings_detail_help_faq_answer_5": "Some modules are part of the Pro version – by default vehicles, port timing, wire gauge, liquid calculator and gearbox. You can buy them via the App Store or use them with an unlocked account.",
        "settings_detail_help_faq_answer_6": "An account enables cloud sync for your vehicles, Pro purchase via the App Store and profile management. You can use calculators without an account.",
        "settings_detail_help_faq_answer_7": "They remind you of due maintenance, MOT dates and expiring insurance for your vehicles. You can change the permission anytime under Settings → Permissions.",
        "settings_detail_help_faq_question_1": "What does 2-Stroke Calc calculate?",
        "settings_detail_help_faq_question_2": "Are my inputs stored?",
        "settings_detail_help_faq_question_3": "What units does the app use?",
        "settings_detail_help_faq_question_4": "How do I change the menu layout?",
        "settings_detail_help_faq_question_5": "What is the Pro version?",
        "settings_detail_help_faq_question_6": "Why do I need an account?",
        "settings_detail_help_faq_question_7": "What are push notifications for?",
        "settings_detail_help_faq_title": "FAQ",
        "settings_detail_help_intro": "Short answers and practical tips for using 2-Stroke Calc – calculators, vehicles, account and Pro version.",
        "settings_detail_help_tip_1": "Double-check all measurements – small errors strongly affect results.",
        "settings_detail_help_tip_2": "Use dark theme in the workshop for better readability.",
        "settings_detail_help_tip_3": "For questions or bugs, reach us via Contact → Send message or Report bug.",
        "settings_detail_help_tip_4": "Link port timing and time-area – the calculators can import values directly.",
        "settings_detail_help_tips_title": "Helpful tips",
        "settings_detail_imprint_intro": "Provider information.",
        "settings_detail_imprint_provider_item_1": "SimplestSoft",
        "settings_detail_imprint_provider_item_2": "support@simplestsoft.com",
        "settings_detail_imprint_provider_title": "Provider",
        "settings_detail_imprint_responsible_item_1": "SimplestSoft (address available on request via support@simplestsoft.com)",
        "settings_detail_imprint_responsible_title": "Responsible for content",
        "settings_detail_privacy_cloud_item_1": "With an account, vehicle data is synced to the cloud via Firebase.",
        "settings_detail_privacy_cloud_item_2": "This includes master data, maintenance entries, fuel log and document references.",
        "settings_detail_privacy_cloud_title": "Cloud data",
        "settings_detail_privacy_intro": "We take data protection seriously. Below is an overview of what data is processed.",
        "settings_detail_privacy_local_item_1": "Calculator inputs are processed on the device and not stored permanently.",
        "settings_detail_privacy_local_item_2": "App settings (theme, language, menu type) are stored locally.",
        "settings_detail_privacy_local_title": "Local data",
        "settings_detail_privacy_notifications_item_1": "Push notifications for maintenance reminders are scheduled locally on the device. No personal data is transmitted to us.",
        "settings_detail_privacy_notifications_title": "Notifications",
        "settings_detail_privacy_purchase_item_1": "Pro purchases are processed via the App Store. Payment data is handled by Apple, not by us.",
        "settings_detail_privacy_purchase_title": "Purchases",
        "settings_detail_processing_account_item_1": "Email address and profile data are stored for authentication and sync.",
        "settings_detail_processing_account_item_2": "Vehicle data is stored in Firebase Firestore and linked only to your account.",
        "settings_detail_processing_account_title": "Account and vehicles",
        "settings_detail_processing_basis_item_1": "Contact and bug reports are processed based on your consent.",
        "settings_detail_processing_basis_item_2": "Account and vehicle data are processed for contract performance (use of app features).",
        "settings_detail_processing_basis_title": "Legal basis",
        "settings_detail_processing_contact_item_1": "Messages are sent via your email app – we only receive what you send.",
        "settings_detail_processing_contact_item_2": "Bug reports optionally include device information for troubleshooting.",
        "settings_detail_processing_contact_title": "Contact and bug reports",
        "settings_detail_processing_intro": "Information about processing personal data under GDPR.",
        "settings_detail_processing_local_item_1": "Theme, language and menu type are stored exclusively on the device.",
        "settings_detail_processing_local_title": "Local settings",
        "settings_detail_terms_account_item_1": "An account is required for cloud sync, Pro purchase and profile management.",
        "settings_detail_terms_account_item_2": "You can delete your account anytime in account settings.",
        "settings_detail_terms_account_title": "Account",
        "settings_detail_terms_intro": "By using 2-Stroke Calc you accept the following terms.",
        "settings_detail_terms_pro_item_1": "Pro version purchases are made via the App Store. Processing, refunds and cancellation follow App Store policies.",
        "settings_detail_terms_pro_item_2": "Which modules require Pro may change. Unlocked purchases remain linked to your Apple ID.",
        "settings_detail_terms_pro_title": "Pro version",
        "settings_detail_terms_usage_item_1": "The app is a helper for technical calculations and vehicle management. Results do not replace professional verification.",
