        "settings_changelog_v10_item_1": "Novos idiomas: dinamarquês, norueguês e sueco disponíveis",
        "settings_changelog_v10_title": "Versão 1.2.7",
        "settings_changelog_v1_item_1": "Atualização da calculadora",
        "settings_changelog_v1_title": "Versão 1.0.0",
        "settings_changelog_v2_item_1": "Modelo Freemium: Visualize todos os computadores e veículos na versão gratuita; Edite, adicione e exclua apenas com Pro",
        "settings_changelog_v2_item_2": "Veículo de demonstração para usuários gratuitos explorarem o gerenciamento de veículos",
        "settings_changelog_v2_item_3": "Caixa de diálogo Pro com descrição do módulo e compra direta no Google Play",
        "settings_changelog_v2_item_4": "Selo Free/Pro no canto superior direito nas configurações",
        "settings_changelog_v2_item_5": "Ajuda atualizada, perguntas frequentes, textos jurídicos e instruções introdutórias",
        "settings_changelog_v2_title": "Versão 1.1.0",
        "settings_changelog_v3_item_1": "Atualização de notificação: lembretes de manutenção aprimorados com agendamento em vários estágios e confirmação diretamente na mensagem push",
        "settings_changelog_v3_item_2": "A quilometragem e as horas de operação nos dados mestre são sincronizadas automaticamente com o livro de combustível",
        "settings_changelog_v3_title": "Versão 1.2.0",
        "settings_changelog_v4_item_1": "Pequenos bugs corrigidos",
        "settings_changelog_v4_title": "Versão 1.2.1",
        "settings_changelog_v5_item_1": "Calculadora de transmissão: As linhas de engrenagem no diagrama conectam-se de forma realista aos pontos de comutação",
        "settings_changelog_v5_item_2": "Transições de comutação tracejadas, buffers nos segmentos de engrenagem e fundo colorido da área Reso",
        "settings_changelog_v5_title": "Versão 1.2.2",
        "settings_changelog_v6_item_1": "Base de dados de veículos: 4000+ modelos com pré-seleções técnicas na criação (marca, modelo, ano de fabricação, variante)",
        "settings_changelog_v6_item_2": "Nova calculadora de dinâmica de condução: aceleração, força de tração, velocidade máxima, necessidade de potência e comparação de marchas",
        "settings_changelog_v6_item_3": "Nova calculadora de volante para rolos de bancada de teste com modos de geometria, massa e simulação",
        "settings_changelog_v6_item_4": "Seleção unificada: a partir de 3 opções, menus suspensos são usados ​​em vez de chips",
        "settings_changelog_v6_title": "Versão 1.2.3",
        "settings_changelog_v7_item_1": "Lançamento de aplicativo mais estável: borda a borda agora é inicializada antes da configuração da IU",
        "settings_changelog_v7_item_2": "Navegação mais robusta: o passo a passo apenas redireciona para uma aba principal quando necessário",
        "settings_changelog_v7_item_3": "Avatar do veículo otimizado: as imagens são carregadas de forma assíncrona e dimensionadas para economizar memória",
        "settings_changelog_v7_item_4": "Sobreposição de passo a passo reformulada: exibição de holofotes mais precisa e bloqueio de toque mais confiável",
        "settings_changelog_v7_title": "Versão 1.2.4",
        "settings_changelog_v8_item_1": "Novos idiomas: espanhol, italiano e português disponíveis",
        "settings_changelog_v8_item_4": "Navegação de veículos estabilizada e diálogos melhorados em telas com recorte",
        "settings_changelog_v8_title": "Versão 1.2.5",
        "settings_changelog_v9_item_1": "Visualização horizontal em tela cheia estabilizada: sem mais congelamento ao girar nas calculadoras de transmissão e escape",
        "settings_changelog_v9_item_2": "Diálogos em tela cheia otimizados: configuração de janela única em vez de reconfigurar a cada redesenho",
        "settings_changelog_v9_title": "Versão 1.2.6",
