        "settings_changelog_v2_item_5": "Uppdaterad hjälp, FAQ, juridiska texter och inledande genomgång",
        "settings_changelog_v2_title": "Version 1.1.0",
        "settings_changelog_v3_item_1": "Uppdatering av meddelanden: förbättrade underhållspåminnelser med schemaläggning i flera steg och bekräftelse direkt i push-meddelandet",
        "settings_changelog_v3_item_2": "Körsträcka och drifttimmar i stamdata synkroniseras automatiskt med bränsleboken",
        "settings_changelog_v3_title": "Version 1.2.0",
        "settings_changelog_v4_item_1": "Mindre buggar fixade",
        "settings_changelog_v4_title": "Version 1.2.1",
        "settings_changelog_v5_item_1": "Transmissionskalkylator: Kugghjulslinjer i diagrammet ansluter realistiskt till kopplingspunkterna",
        "settings_changelog_v5_item_2": "Streckade växlingsövergångar, buffertar på kugghjulssegmenten och färgad bakgrund i Reso-området",
        "settings_changelog_v5_title": "Version 1.2.2",
        "settings_changelog_v6_item_1": "Fordonsdatabas: 4000+ modeller med tekniska förval vid skapande (märke, modell, konstruktionsår, variant)",
        "settings_changelog_v6_item_2": "Ny kördynamikräknare: acceleration, dragkraft, topphastighet, effektbehov och växeljämförelse",
        "settings_changelog_v6_item_3": "Ny svänghjulskalkylator för testbänkrullar med geometri, massa och simuleringslägen",
        "settings_changelog_v6_item_4": "Enhetligt urval: från 3 alternativ och framåt används rullgardinsmenyn istället för marker",
        "settings_changelog_v6_title": "Version 1.2.3",
        "settings_changelog_v7_item_1": "Stabilare applansering: Kant-till-kant initieras nu innan användargränssnittet konfigureras",
        "settings_changelog_v7_item_2": "Navigering mer robust: Walkthrough omdirigerar bara till en huvudflik när det behövs",
        "settings_changelog_v7_item_3": "Fordonsavatar optimerad: Bilder laddas asynkront och skalas för att spara minne",
        "settings_changelog_v7_item_4": "Genomgångsöverlägget omarbetat: mer exakt spotlight-display och mer pålitlig beröringsblockering",
        "settings_changelog_v7_title": "Version 1.2.4",
        "settings_changelog_v8_item_1": "Nya språk: spanska, italienska och portugisiska tillgängliga",
        "settings_changelog_v8_item_4": "Fordonsnavigering stabiliserad och dialogrutorna förbättrade på enheter med en skärmutskärning",
        "settings_changelog_v8_title": "Version 1.2.5",
        "settings_changelog_v9_item_1": "Landskapsvy i helskärm stabiliserad: Inget mer frysning när du vrider i växeln och avgaskalkylatorn",
        "settings_changelog_v9_item_2": "Helskärmsdialoger optimerade: fönsterkonfiguration en gång istället för varje omritning",
        "settings_changelog_v9_title": "Version 1.2.6",
