        "settings_changelog_v2_title": "Version 1.1.0",
        "settings_changelog_v3_item_1": "Notifikationsopdatering: forbedrede vedligeholdelsespåmindelser med flertrinsplanlægning og bekræftelse direkte i push-meddelelsen",
        "settings_changelog_v3_item_2": "Kilometertal og driftstimer i stamdata synkroniseres automatisk med brændstofbogen",
        "settings_changelog_v3_title": "Version 1.2.0",
        "settings_changelog_v4_item_1": "Mindre fejl rettet",
        "settings_changelog_v4_title": "Version 1.2.1",
        "settings_changelog_v5_item_1": "Transmissionsberegner: Gearlinjerne i diagrammet forbindes realistisk med koblingspunkterne",
        "settings_changelog_v5_item_2": "Stiplede skifteovergange, buffere på gearsegmenterne og farvet baggrund i Reso-området",
        "settings_changelog_v5_title": "Version 1.2.2",
        "settings_changelog_v6_item_1": "Køretøjsdatabase: 4000+ modeller med tekniske forudvalg ved oprettelse (mærke, model, byggeår, variant)",
        "settings_changelog_v6_item_2": "Ny køredynamikberegner: acceleration, trækkraft, tophastighed, kraftbehov og gearsammenligning",
        "settings_changelog_v6_item_3": "Ny svinghjulsberegner til testbænkruller med geometri, masse og simuleringstilstande",
        "settings_changelog_v6_item_4": "Samlet udvalg: Fra 3 muligheder og fremefter bruges dropdowns i stedet for chips",
        "settings_changelog_v6_title": "Version 1.2.3",
        "settings_changelog_v7_item_1": "Mere stabil app-lancering: Edge-to-edge er nu initialiseret før UI-opsætning",
        "settings_changelog_v7_item_2": "Navigation mere robust: Walkthrough omdirigerer kun til en hovedfane, når det er nødvendigt",
        "settings_changelog_v7_item_3": "Køretøjsavatar optimeret: Billeder indlæses asynkront og skaleres for at spare hukommelse",
        "settings_changelog_v7_item_4": "Walkthrough-overlay omarbejdet: mere præcist spotlight-display og mere pålidelig berøringsblokering",
        "settings_changelog_v7_title": "Version 1.2.4",
        "settings_changelog_v8_item_1": "Nye sprog: spansk, italiensk og portugisisk tilgængelige",
        "settings_changelog_v8_item_4": "Køretøjsnavigation stabiliseret og dialogbokse forbedret på enheder med en skærmudskæring",
        "settings_changelog_v8_title": "Version 1.2.5",
        "settings_changelog_v9_item_1": "Landskabsvisning i fuld skærm stabiliseret: Ikke mere at fryse, når du drejer gear og udstødningsberegner",
        "settings_changelog_v9_item_2": "Fuldskærmsdialoger optimeret: vindueskonfiguration én gang i stedet for hver gentegning",
        "settings_changelog_v9_title": "Version 1.2.6",
