        "settings_changelog_v10_item_1": "Nye språk: dansk, norsk og svensk tilgjengelige",
        "settings_changelog_v10_title": "Versjon 1.2.7",
        "settings_changelog_v1_item_1": "Kalkulatoroppdatering",
        "settings_changelog_v1_title": "Versjon 1.0.0",
        "settings_changelog_v2_item_1": "Freemium-modell: Se alle datamaskiner og kjøretøy i gratisversjonen; Rediger, legg til og slett kun med Pro",
        "settings_changelog_v2_item_2": "Demokjøretøy for gratisbrukere for å utforske kjøretøyadministrasjon",
        "settings_changelog_v2_item_3": "Pro-dialog med modulbeskrivelse og direkte Google Play-kjøp",
        "settings_changelog_v2_item_4": "Gratis/Pro-merket øverst til høyre i innstillingene",
        "settings_changelog_v2_item_5": "Oppdatert hjelp, FAQ, juridiske tekster og innledende gjennomgang",
        "settings_changelog_v2_title": "Versjon 1.1.0",
        "settings_changelog_v3_item_1": "Varslingsoppdatering: forbedrede vedlikeholdspåminnelser med flertrinnsplanlegging og bekreftelse direkte i push-meldingen",
        "settings_changelog_v3_item_2": "Kilometerstand og driftstimer i stamdataene synkroniseres automatisk med drivstoffboken",
        "settings_changelog_v3_title": "Versjon 1.2.0",
        "settings_changelog_v4_item_1": "Mindre feil fikset",
        "settings_changelog_v4_title": "Versjon 1.2.1",
        "settings_changelog_v5_item_1": "Transmisjonskalkulator: Girlinjer i diagrammet kobles realistisk til koblingspunktene",
        "settings_changelog_v5_item_2": "Stiplede bytteoverganger, buffere på girsegmentene og farget bakgrunn i Reso-området",
        "settings_changelog_v5_title": "Versjon 1.2.2",
        "settings_changelog_v6_item_1": "Kjøretøydatabase: 4000+ modeller med tekniske forhåndsvalg ved oppretting (merke, modell, byggeår, variant)",
        "settings_changelog_v6_item_2": "Ny kjøredynamikkkalkulator: akselerasjon, trekkraft, topphastighet, kraftbehov og girsammenligning",
        "settings_changelog_v6_item_3": "Ny svinghjulskalkulator for testbenkruller med geometri, masse og simuleringsmodus",
        "settings_changelog_v6_item_4": "Samlet utvalg: fra 3 alternativer og utover brukes rullegardinmenyene i stedet for sjetonger",
        "settings_changelog_v6_title": "Versjon 1.2.3",
        "settings_changelog_v7_item_1": "Mer stabil applansering: Edge-to-edge er nå initialisert før UI-oppsett",
        "settings_changelog_v7_item_2": "Navigasjon mer robust: Walkthrough omdirigerer bare til en hovedfane når det er nødvendig",
        "settings_changelog_v7_item_3": "Kjøretøyavatar optimalisert: Bilder lastes inn asynkront og skaleres for å spare minne",
        "settings_changelog_v7_item_4": "Gjennomgangsoverlegg omarbeidet: mer presis spotlight-skjerm og mer pålitelig berøringsblokkering",
        "settings_changelog_v7_title": "Versjon 1.2.4",
        "settings_changelog_v8_item_1": "Nye språk: spansk, italiensk og portugisisk tilgjengelig",
        "settings_changelog_v8_item_4": "Kjøretøynavigasjon stabilisert og dialoger forbedret på enheter med skjermutskjæring",
        "settings_changelog_v8_title": "Versjon 1.2.5",
        "settings_changelog_v9_item_1": "Landskapsvisning i full skjerm stabilisert: Ikke mer å fryse når du slår inn gir- og eksoskalkulatoren",
        "settings_changelog_v9_item_2": "Fullskjermdialoger optimalisert: vinduskonfigurasjon én gang i stedet for hver omtegning",
        "settings_changelog_v9_title": "Versjon 1.2.6",
